package database

import (
	"database/sql"
	"fmt"
	_ "github.com/mattn/go-sqlite3"
	"log"
)

type DB struct {
	*sql.DB
}

// InitDB 데이터베이스 초기화
func InitDB(filepath string) (*DB, error) {
	sqlDB, err := sql.Open("sqlite3", filepath)
	if err != nil {
		return nil, fmt.Errorf("데이터베이스 연결 실패: %w", err)
	}

	if err := sqlDB.Ping(); err != nil {
		return nil, fmt.Errorf("데이터베이스 핑 실패: %w", err)
	}

	db := &DB{sqlDB}

	// 테이블 생성
	if err := db.createTables(); err != nil {
		return nil, err
	}

	log.Println("✅ 데이터베이스 초기화 완료")
	return db, nil
}

// createTables 필요한 모든 테이블 생성
func (db *DB) createTables() error {
	queries := []string{
		// 계좌 테이블
		`CREATE TABLE IF NOT EXISTS accounts (
			id TEXT PRIMARY KEY,
			name TEXT NOT NULL,
			type TEXT NOT NULL,
			balance REAL NOT NULL,
			rate REAL NOT NULL DEFAULT 0.0,
			status TEXT NOT NULL DEFAULT 'active',
			created_at INTEGER NOT NULL,
			updated_at INTEGER NOT NULL
		)`,

		// 거래 테이블
		`CREATE TABLE IF NOT EXISTS transactions (
			id TEXT PRIMARY KEY,
			from_account_id TEXT,
			to_account_id TEXT,
			amount REAL NOT NULL,
			fee REAL NOT NULL DEFAULT 0.0,
			type TEXT NOT NULL,
			status TEXT NOT NULL DEFAULT 'pending',
			description TEXT,
			created_at INTEGER NOT NULL,
			completed_at INTEGER
		)`,

		// 감시 로그 테이블
		`CREATE TABLE IF NOT EXISTS audit_logs (
			id TEXT PRIMARY KEY,
			action TEXT NOT NULL,
			account_id TEXT,
			description TEXT,
			ip_address TEXT,
			user_agent TEXT,
			timestamp INTEGER NOT NULL
		)`,

		// 사기 경고 테이블
		`CREATE TABLE IF NOT EXISTS fraud_alerts (
			id TEXT PRIMARY KEY,
			transaction_id TEXT,
			severity TEXT NOT NULL,
			score INTEGER NOT NULL,
			reason TEXT,
			timestamp INTEGER NOT NULL
		)`,

		// 이자 기록 테이블
		`CREATE TABLE IF NOT EXISTS interest_records (
			id TEXT PRIMARY KEY,
			account_id TEXT NOT NULL,
			amount REAL NOT NULL,
			rate REAL NOT NULL,
			period TEXT NOT NULL,
			timestamp INTEGER NOT NULL
		)`,
	}

	for _, query := range queries {
		if _, err := db.Exec(query); err != nil {
			return fmt.Errorf("테이블 생성 실패: %w", err)
		}
	}

	return nil
}

// Account 레코드
type Account struct {
	ID        string  `json:"id"`
	Name      string  `json:"name"`
	Type      string  `json:"type"`
	Balance   float64 `json:"balance"`
	Rate      float64 `json:"rate"`
	Status    string  `json:"status"`
	CreatedAt int64  `json:"created_at"`
	UpdatedAt int64  `json:"updated_at"`
}

// Transaction 레코드
type Transaction struct {
	ID               string  `json:"id"`
	FromAccountID    string  `json:"from_account_id"`
	ToAccountID      string  `json:"to_account_id"`
	Amount           float64 `json:"amount"`
	Fee              float64 `json:"fee"`
	Type             string  `json:"type"`
	Status           string  `json:"status"`
	Description      string  `json:"description"`
	CreatedAt        int64  `json:"created_at"`
	CompletedAt      *int64 `json:"completed_at,omitempty"`
}

// AuditLog 레코드
type AuditLog struct {
	ID        string `json:"id"`
	Action    string `json:"action"`
	AccountID string `json:"account_id"`
	Description string `json:"description"`
	IPAddress string `json:"ip_address"`
	UserAgent string `json:"user_agent"`
	Timestamp int64  `json:"timestamp"`
}

// FraudAlert 레코드
type FraudAlert struct {
	ID            string `json:"id"`
	TransactionID string `json:"transaction_id"`
	Severity      string `json:"severity"`
	Score         int    `json:"score"`
	Reason        string `json:"reason"`
	Timestamp     int64  `json:"timestamp"`
}

// InterestRecord 레코드
type InterestRecord struct {
	ID        string  `json:"id"`
	AccountID string  `json:"account_id"`
	Amount    float64 `json:"amount"`
	Rate      float64 `json:"rate"`
	Period    string  `json:"period"`
	Timestamp int64  `json:"timestamp"`
}

package handlers

import (
	"github.com/gin-gonic/gin"
	"github.com/google/uuid"
	"net/http"
	"time"
	"freelang-bank-system/server/database"
)

type AccountHandler struct {
	db *database.DB
}

func NewAccountHandler(db *database.DB) *AccountHandler {
	return &AccountHandler{db: db}
}

type CreateAccountRequest struct {
	Name string  `json:"name" binding:"required"`
	Type string  `json:"type" binding:"required"`
	Rate float64 `json:"rate"`
}

type CreateAccountResponse struct {
	ID        string  `json:"id"`
	Name      string  `json:"name"`
	Type      string  `json:"type"`
	Balance   float64 `json:"balance"`
	Status    string  `json:"status"`
	Message   string  `json:"message"`
}

// CreateAccount POST /api/accounts
func (h *AccountHandler) CreateAccount(c *gin.Context) {
	var req CreateAccountRequest
	if err := c.ShouldBindJSON(&req); err != nil {
		c.JSON(http.StatusBadRequest, gin.H{
			"error": "Bad Request",
			"message": "잘못된 요청: " + err.Error(),
		})
		return
	}

	// 계좌 생성
	account := database.Account{
		ID:        "ACC" + uuid.New().String()[:8],
		Name:      req.Name,
		Type:      req.Type,
		Balance:   0.0,
		Rate:      req.Rate,
		Status:    "active",
		CreatedAt: time.Now().Unix(),
		UpdatedAt: time.Now().Unix(),
	}

	// 데이터베이스에 저장
	_, err := h.db.Exec(
		`INSERT INTO accounts (id, name, type, balance, rate, status, created_at, updated_at)
		 VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
		account.ID, account.Name, account.Type, account.Balance, account.Rate,
		account.Status, account.CreatedAt, account.UpdatedAt,
	)

	if err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{
			"error": "Internal Server Error",
			"message": "계좌 생성 실패: " + err.Error(),
		})
		return
	}

	// 감시 로그 기록
	h.logAudit("ACCOUNT_CREATED", account.ID, "새 계좌 생성", c.ClientIP(), c.Request.UserAgent())

	c.JSON(http.StatusCreated, CreateAccountResponse{
		ID:      account.ID,
		Name:    account.Name,
		Type:    account.Type,
		Balance: account.Balance,
		Status:  account.Status,
		Message: "계좌 생성 완료",
	})
}

// ListAccounts GET /api/accounts
func (h *AccountHandler) ListAccounts(c *gin.Context) {
	rows, err := h.db.Query(`SELECT id, name, type, balance, rate, status, created_at, updated_at FROM accounts`)
	if err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{
			"error": "Internal Server Error",
			"message": "계좌 목록 조회 실패: " + err.Error(),
		})
		return
	}
	defer rows.Close()

	var accounts []database.Account
	for rows.Next() {
		var acc database.Account
		if err := rows.Scan(&acc.ID, &acc.Name, &acc.Type, &acc.Balance, &acc.Rate,
			&acc.Status, &acc.CreatedAt, &acc.UpdatedAt); err != nil {
			c.JSON(http.StatusInternalServerError, gin.H{
				"error": "Internal Server Error",
				"message": "행 스캔 실패: " + err.Error(),
			})
			return
		}
		accounts = append(accounts, acc)
	}

	c.JSON(http.StatusOK, gin.H{
		"accounts": accounts,
		"count":    len(accounts),
	})
}

// GetAccount GET /api/accounts/:id
func (h *AccountHandler) GetAccount(c *gin.Context) {
	id := c.Param("id")

	var account database.Account
	err := h.db.QueryRow(
		`SELECT id, name, type, balance, rate, status, created_at, updated_at FROM accounts WHERE id = ?`,
		id,
	).Scan(&account.ID, &account.Name, &account.Type, &account.Balance, &account.Rate,
		&account.Status, &account.CreatedAt, &account.UpdatedAt)

	if err != nil {
		c.JSON(http.StatusNotFound, gin.H{
			"error": "Not Found",
			"message": "계좌를 찾을 수 없습니다: " + id,
		})
		return
	}

	c.JSON(http.StatusOK, account)
}

type UpdateAccountRequest struct {
	Name   string  `json:"name"`
	Status string  `json:"status"`
	Rate   float64 `json:"rate"`
}

// UpdateAccount PUT /api/accounts/:id
func (h *AccountHandler) UpdateAccount(c *gin.Context) {
	id := c.Param("id")
	var req UpdateAccountRequest
	if err := c.ShouldBindJSON(&req); err != nil {
		c.JSON(http.StatusBadRequest, gin.H{
			"error": "Bad Request",
			"message": "잘못된 요청: " + err.Error(),
		})
		return
	}

	// 기존 계좌 확인
	var account database.Account
	err := h.db.QueryRow(
		`SELECT id, name, type, balance, rate, status, created_at, updated_at FROM accounts WHERE id = ?`,
		id,
	).Scan(&account.ID, &account.Name, &account.Type, &account.Balance, &account.Rate,
		&account.Status, &account.CreatedAt, &account.UpdatedAt)

	if err != nil {
		c.JSON(http.StatusNotFound, gin.H{
			"error": "Not Found",
			"message": "계좌를 찾을 수 없습니다: " + id,
		})
		return
	}

	// 업데이트
	if req.Name != "" {
		account.Name = req.Name
	}
	if req.Status != "" {
		account.Status = req.Status
	}
	if req.Rate > 0 {
		account.Rate = req.Rate
	}
	account.UpdatedAt = time.Now().Unix()

	_, err = h.db.Exec(
		`UPDATE accounts SET name = ?, status = ?, rate = ?, updated_at = ? WHERE id = ?`,
		account.Name, account.Status, account.Rate, account.UpdatedAt, id,
	)

	if err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{
			"error": "Internal Server Error",
			"message": "계좌 업데이트 실패: " + err.Error(),
		})
		return
	}

	// 감시 로그 기록
	h.logAudit("ACCOUNT_UPDATED", id, "계좌 업데이트", c.ClientIP(), c.Request.UserAgent())

	c.JSON(http.StatusOK, gin.H{
		"id":     id,
		"status": "updated",
		"message": "계좌 업데이트 완료",
	})
}

// DeleteAccount DELETE /api/accounts/:id
func (h *AccountHandler) DeleteAccount(c *gin.Context) {
	id := c.Param("id")

	// 계좌 존재 확인
	var exists int
	err := h.db.QueryRow(`SELECT COUNT(*) FROM accounts WHERE id = ?`, id).Scan(&exists)
	if err != nil || exists == 0 {
		c.JSON(http.StatusNotFound, gin.H{
			"error": "Not Found",
			"message": "계좌를 찾을 수 없습니다: " + id,
		})
		return
	}

	_, err = h.db.Exec(`DELETE FROM accounts WHERE id = ?`, id)
	if err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{
			"error": "Internal Server Error",
			"message": "계좌 삭제 실패: " + err.Error(),
		})
		return
	}

	// 감시 로그 기록
	h.logAudit("ACCOUNT_DELETED", id, "계좌 삭제", c.ClientIP(), c.Request.UserAgent())

	c.JSON(http.StatusNoContent, nil)
}

// logAudit 감시 로그 기록
func (h *AccountHandler) logAudit(action, accountID, description, ipAddress, userAgent string) {
	auditLog := database.AuditLog{
		ID:          "AUDIT-" + uuid.New().String()[:8],
		Action:      action,
		AccountID:   accountID,
		Description: description,
		IPAddress:   ipAddress,
		UserAgent:   userAgent,
		Timestamp:   time.Now().Unix(),
	}

	_, err := h.db.Exec(
		`INSERT INTO audit_logs (id, action, account_id, description, ip_address, user_agent, timestamp)
		 VALUES (?, ?, ?, ?, ?, ?, ?)`,
		auditLog.ID, auditLog.Action, auditLog.AccountID, auditLog.Description,
		auditLog.IPAddress, auditLog.UserAgent, auditLog.Timestamp,
	)

	if err != nil {
		// 로그 기록 실패는 무시
	}
}

package handlers

import (
	"github.com/gin-gonic/gin"
	"github.com/google/uuid"
	"net/http"
	"time"
	"freelang-bank-system/server/database"
)

type TransactionHandler struct {
	db *database.DB
}

func NewTransactionHandler(db *database.DB) *TransactionHandler {
	return &TransactionHandler{db: db}
}

type CreateTransactionRequest struct {
	FromAccountID string  `json:"from_account_id" binding:"required"`
	ToAccountID   string  `json:"to_account_id" binding:"required"`
	Amount        float64 `json:"amount" binding:"required,gt=0"`
	Type          string  `json:"type" binding:"required"`
	Description   string  `json:"description"`
}

// CreateTransaction POST /api/transactions
func (h *TransactionHandler) CreateTransaction(c *gin.Context) {
	var req CreateTransactionRequest
	if err := c.ShouldBindJSON(&req); err != nil {
		c.JSON(http.StatusBadRequest, gin.H{
			"error": "Bad Request",
			"message": "잘못된 요청: " + err.Error(),
		})
		return
	}

	// 송금 계좌 존재 확인
	var fromBalance float64
	err := h.db.QueryRow(`SELECT balance FROM accounts WHERE id = ?`, req.FromAccountID).Scan(&fromBalance)
	if err != nil {
		c.JSON(http.StatusNotFound, gin.H{
			"error": "Not Found",
			"message": "송금 계좌를 찾을 수 없습니다",
		})
		return
	}

	// 수취 계좌 존재 확인
	var toBalance float64
	err = h.db.QueryRow(`SELECT balance FROM accounts WHERE id = ?`, req.ToAccountID).Scan(&toBalance)
	if err != nil {
		c.JSON(http.StatusNotFound, gin.H{
			"error": "Not Found",
			"message": "수취 계좌를 찾을 수 없습니다",
		})
		return
	}

	// 잔액 확인
	fee := req.Amount * 0.002 // 0.2% 수수료
	totalAmount := req.Amount + fee

	if fromBalance < totalAmount {
		c.JSON(http.StatusBadRequest, gin.H{
			"error": "Insufficient Balance",
			"message": "잔액 부족",
			"required": totalAmount,
			"balance": fromBalance,
		})
		return
	}

	// 거래 생성
	now := time.Now().Unix()
	transaction := database.Transaction{
		ID:            "TXN-" + uuid.New().String()[:8],
		FromAccountID: req.FromAccountID,
		ToAccountID:   req.ToAccountID,
		Amount:        req.Amount,
		Fee:           fee,
		Type:          req.Type,
		Status:        "pending",
		Description:   req.Description,
		CreatedAt:     now,
	}

	// 거래 저장
	_, err = h.db.Exec(
		`INSERT INTO transactions (id, from_account_id, to_account_id, amount, fee, type, status, description, created_at)
		 VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`,
		transaction.ID, transaction.FromAccountID, transaction.ToAccountID,
		transaction.Amount, transaction.Fee, transaction.Type, transaction.Status,
		transaction.Description, transaction.CreatedAt,
	)

	if err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{
			"error": "Internal Server Error",
			"message": "거래 저장 실패: " + err.Error(),
		})
		return
	}

	// 계좌 업데이트 (출금/입금)
	newFromBalance := fromBalance - totalAmount
	newToBalance := toBalance + req.Amount

	h.db.Exec(`UPDATE accounts SET balance = ?, updated_at = ? WHERE id = ?`,
		newFromBalance, now, req.FromAccountID)
	h.db.Exec(`UPDATE accounts SET balance = ?, updated_at = ? WHERE id = ?`,
		newToBalance, now, req.ToAccountID)

	// 거래 완료 처리
	h.db.Exec(`UPDATE transactions SET status = ?, completed_at = ? WHERE id = ?`,
		"completed", now, transaction.ID)

	// 감시 로그 기록
	h.logAudit("TRANSACTION_COMPLETED", req.FromAccountID, "거래 완료: "+transaction.ID, c.ClientIP(), c.Request.UserAgent())

	c.JSON(http.StatusCreated, gin.H{
		"id":                transaction.ID,
		"from_account_id":   transaction.FromAccountID,
		"to_account_id":     transaction.ToAccountID,
		"amount":            transaction.Amount,
		"fee":               transaction.Fee,
		"status":            "completed",
		"message":           "거래 완료",
	})
}

// GetTransaction GET /api/transactions/:id
func (h *TransactionHandler) GetTransaction(c *gin.Context) {
	id := c.Param("id")

	var txn database.Transaction
	err := h.db.QueryRow(
		`SELECT id, from_account_id, to_account_id, amount, fee, type, status, description, created_at, completed_at
		 FROM transactions WHERE id = ?`,
		id,
	).Scan(&txn.ID, &txn.FromAccountID, &txn.ToAccountID, &txn.Amount, &txn.Fee,
		&txn.Type, &txn.Status, &txn.Description, &txn.CreatedAt, &txn.CompletedAt)

	if err != nil {
		c.JSON(http.StatusNotFound, gin.H{
			"error": "Not Found",
			"message": "거래를 찾을 수 없습니다: " + id,
		})
		return
	}

	c.JSON(http.StatusOK, txn)
}

// GetAccountTransactions GET /api/accounts/:id/transactions
func (h *TransactionHandler) GetAccountTransactions(c *gin.Context) {
	accountID := c.Param("id")

	rows, err := h.db.Query(
		`SELECT id, from_account_id, to_account_id, amount, fee, type, status, description, created_at, completed_at
		 FROM transactions WHERE from_account_id = ? OR to_account_id = ? ORDER BY created_at DESC LIMIT 100`,
		accountID, accountID,
	)
	if err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{
			"error": "Internal Server Error",
			"message": "거래 조회 실패: " + err.Error(),
		})
		return
	}
	defer rows.Close()

	var transactions []database.Transaction
	for rows.Next() {
		var txn database.Transaction
		if err := rows.Scan(&txn.ID, &txn.FromAccountID, &txn.ToAccountID,
			&txn.Amount, &txn.Fee, &txn.Type, &txn.Status,
			&txn.Description, &txn.CreatedAt, &txn.CompletedAt); err != nil {
			continue
		}
		transactions = append(transactions, txn)
	}

	c.JSON(http.StatusOK, gin.H{
		"account_id":    accountID,
		"transactions":  transactions,
		"count":         len(transactions),
	})
}

type ReverseTransactionRequest struct {
	TransactionID string `json:"transaction_id" binding:"required"`
}

// ReverseTransaction POST /api/transactions/reverse
func (h *TransactionHandler) ReverseTransaction(c *gin.Context) {
	var req ReverseTransactionRequest
	if err := c.ShouldBindJSON(&req); err != nil {
		c.JSON(http.StatusBadRequest, gin.H{
			"error": "Bad Request",
			"message": "잘못된 요청: " + err.Error(),
		})
		return
	}

	// 원본 거래 조회
	var txn database.Transaction
	var fromBalance, toBalance float64

	err := h.db.QueryRow(
		`SELECT id, from_account_id, to_account_id, amount, fee, type, status, description, created_at, completed_at
		 FROM transactions WHERE id = ?`,
		req.TransactionID,
	).Scan(&txn.ID, &txn.FromAccountID, &txn.ToAccountID, &txn.Amount, &txn.Fee,
		&txn.Type, &txn.Status, &txn.Description, &txn.CreatedAt, &txn.CompletedAt)

	if err != nil {
		c.JSON(http.StatusNotFound, gin.H{
			"error": "Not Found",
			"message": "거래를 찾을 수 없습니다",
		})
		return
	}

	// 계좌 잔액 조회
	h.db.QueryRow(`SELECT balance FROM accounts WHERE id = ?`, txn.FromAccountID).Scan(&fromBalance)
	h.db.QueryRow(`SELECT balance FROM accounts WHERE id = ?`, txn.ToAccountID).Scan(&toBalance)

	now := time.Now().Unix()

	// 원본 거래 취소 처리
	h.db.Exec(`UPDATE transactions SET status = ? WHERE id = ?`, "reversed", req.TransactionID)

	// 역거래 생성
	reverseID := "TXN-" + uuid.New().String()[:8]
	h.db.Exec(
		`INSERT INTO transactions (id, from_account_id, to_account_id, amount, fee, type, status, description, created_at, completed_at)
		 VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
		reverseID, txn.ToAccountID, txn.FromAccountID, txn.Amount, txn.Fee,
		"reverse", "completed", "거래 취소: "+req.TransactionID, now, now,
	)

	// 계좌 잔액 복구
	newFromBalance := fromBalance + txn.Amount + txn.Fee
	newToBalance := toBalance - txn.Amount

	h.db.Exec(`UPDATE accounts SET balance = ?, updated_at = ? WHERE id = ?`,
		newFromBalance, now, txn.FromAccountID)
	h.db.Exec(`UPDATE accounts SET balance = ?, updated_at = ? WHERE id = ?`,
		newToBalance, now, txn.ToAccountID)

	// 감시 로그 기록
	h.logAudit("TRANSACTION_REVERSED", txn.FromAccountID, "거래 취소: "+req.TransactionID, c.ClientIP(), c.Request.UserAgent())

	c.JSON(http.StatusOK, gin.H{
		"original_transaction_id": req.TransactionID,
		"reverse_transaction_id":  reverseID,
		"status":                  "reversed",
		"message":                 "거래 취소 완료",
	})
}

// logAudit 감시 로그 기록
func (h *TransactionHandler) logAudit(action, accountID, description, ipAddress, userAgent string) {
	auditLog := database.AuditLog{
		ID:          "AUDIT-" + uuid.New().String()[:8],
		Action:      action,
		AccountID:   accountID,
		Description: description,
		IPAddress:   ipAddress,
		UserAgent:   userAgent,
		Timestamp:   time.Now().Unix(),
	}

