	json.Unmarshal(w.Body.Bytes(), &resp)

	severity := resp["severity"].(string)
	if severity != "critical" {
		t.Errorf("Expected critical severity, got %s", severity)
		return
	}

	t.Logf("✅ Test 3: 사기 탐지 (Critical) - PASS")
}

