		return
	}

	t.Logf("✅ Test 3: 사기 탐지 (Critical) - PASS")
}

// Test 4: 거래 취소 기능
func TestReverseTransaction(t *testing.T) {
	router := setupRouter()

	// 계좌 생성
	createAccReq := map[string]interface{}{
		"name": "David",
		"type": "Checking",
	}
	body, _ := json.Marshal(createAccReq)
