	}

	t.Logf("✅ Test 7: 월간 리포트 - PASS")
}

// 전체 통합 테스트
func TestAllIntegration(t *testing.T) {
	log.Println("\n📋 FreeLang Bank System - Integration Tests (Critical Issues Fix)")
	log.Println("============================================================")

	TestCreateAccountAndBalance(t)
	TestDepositAndCheckBalance(t)
