	} else {
		t.Logf("✅ Test 5: 인증 없이 프로필 조회 검증 - PASS")
	}
}

// Test 6: 중복 이메일 등록 시도
func TestDuplicateEmail(t *testing.T) {
	router := setupAuthRouter()

	req := map[string]interface{}{
		"username": "user1",
