	}

	// 중복 이메일로 등록 시도
	req["username"] = "user2"
	body, _ = json.Marshal(req)

	w = httptest.NewRecorder()
	httpReq, _ = http.NewRequest("POST", "/api/auth/register", bytes.NewBuffer(body))
	httpReq.Header.Set("Content-Type", "application/json")
