	} else {
		t.Logf("✅ Test 6: 중복 이메일 검증 - PASS")
	}
}

// 전체 Auth 테스트
func TestAuthSuite(t *testing.T) {
	log.Println("\n📋 FreeLang Bank System - Auth Tests (JWT Implementation)")
	log.Println("============================================================")

	TestRegisterUser(t)
	TestLoginUser(t)
