                value={password}
                onChange={(e) => setPassword(e.target.value)}
                placeholder="8자 이상"
                style={{
                  width: "100%",
                  padding: "10px",
                  border: "1px solid #bdc3c7",
                  borderRadius: "4px",
                  fontSize: "14px",
                  boxSizing: "border-box",
                }}
              />
            </div>

            <button
              type="submit"
              disabled={loading}
              style={{
                width: "100%",
                padding: "12px",
                backgroundColor: loading ? "#bdc3c7" : "#27ae60",
                color: "white",
                border: "none",
                borderRadius: "4px",
                fontWeight: "bold",
                cursor: loading ? "not-allowed" : "pointer",
                fontSize: "14px",
                transition: "all 0.3s",
              }}
            >
              {loading ? "회원가입 중..." : "회원가입"}
            </button>
          </form>
        )}

        {/* 정보 */}
        <div
          style={{
            marginTop: "20px",
            padding: "15px",
            backgroundColor: "#ecf0f1",
            borderRadius: "4px",
            fontSize: "12px",
            color: "#7f8c8d",
            textAlign: "center",
          }}
        >
          <p style={{ margin: "0" }}>
            🔒 모든 거래는 SSL 암호화로 보호됩니다
          </p>
          <p style={{ margin: "5px 0 0 0" }}>
            안전한 JWT 인증 시스템을 사용합니다
          </p>
        </div>
      </div>
    </div>
  );
};

