   * 로그아웃
   */
  logout(): void {
    localStorage.removeItem("token");
    localStorage.removeItem("user_id");
    localStorage.removeItem("username");
  }

  // 🏥 헬스 체크

  /**
   * 서버 헬스 체크
   */
  async healthCheck(): Promise<boolean> {
    try {
      const response = await this.api.get("/health");
      return response.data.status === "OK";
    } catch {
      return false;
    }
  }
}

