          {activeTab === "transactions" && (
            <div style={{ padding: "20px" }}>
              <h2>💳 거래 내역</h2>
              {selectedAccount ? (
                transactions.length === 0 ? (
                  <p>거래 내역이 없습니다</p>
                ) : (
                  <div
                    style={{
                      display: "grid",
                      gridTemplateColumns: "repeat(auto-fill, minmax(300px, 1fr))",
                      gap: "15px",
                    }}
                  >
                    {transactions.map((txn) => (
                      <div
                        key={txn.id}
                        style={{
                          border: "1px solid #ddd",
                          borderRadius: "8px",
                          padding: "15px",
                          backgroundColor: "#f8f9fa",
                        }}
                      >
                        <div style={{ fontWeight: "bold", marginBottom: "10px" }}>
                          {txn.type}
                        </div>
                        <div style={{ fontSize: "12px", marginBottom: "5px" }}>
                          <strong>ID:</strong> {txn.id}
                        </div>
                        <div
                          style={{
                            fontSize: "20px",
                            fontWeight: "bold",
                            color: txn.type === "Deposit" ? "#2ecc71" : "#e74c3c",
                            marginBottom: "10px",
                          }}
                        >
                          {txn.type === "Deposit" ? "+" : "-"}${txn.amount.toFixed(2)}
                        </div>
                        <div style={{ fontSize: "12px" }}>
                          수수료: ${txn.fee.toFixed(2)}
                        </div>
                        <div
                          style={{
                            fontSize: "12px",
                            marginTop: "10px",
                            padding: "5px",
                            backgroundColor: txn.status === "completed" ? "#d4edda" : "#fff3cd",
                            borderRadius: "4px",
                            textAlign: "center",
                          }}
                        >
                          {txn.status === "completed" ? "✅" : "⏳"} {txn.status}
                        </div>
                      </div>
                    ))}
                  </div>
                )
              ) : (
                <p>계좌를 선택하세요</p>
              )}
            </div>
          )}

          {activeTab === "fraud" && <FraudDetection />}
        </div>
      </div>

      {/* 푸터 */}
      <footer
        style={{
          backgroundColor: "#2c3e50",
          color: "white",
          padding: "20px",
          textAlign: "center",
          marginTop: "40px",
        }}
      >
        <p style={{ margin: 0 }}>
          🏦 FreeLang Bank System - Phase 5 React Dashboard | v1.0.0
        </p>
      </footer>
    </div>
  );
};

export default Dashboard;

